import { NextResponse } from "next/server";
import { COPY } from "@/copy";

/**
 * The letter's endpoint, ported from ~/CompoundLabs/thismuchweknow/src/app/api/subscribe/route.ts.
 *
 * ⛔ THE ONE CHANGE IS THAT THE SUPABASE CLIENT IS IMPORTED WHEN IT IS USED, not at module load.
 * This tree carries no env and deploys nowhere, so a top level import would make the whole app
 * depend on a package it can never call. The behaviour is the live route's, unchanged: with no
 * store configured this answers 500 and the form prints copy.ts's own `fail` line.
 *
 * ⛔ AND IT NEVER ANSWERS `ok` WITH NOWHERE TO PUT THE ADDRESS. That is the bug the live route is
 * itself a rewrite of: four publications told a reader "You're on the list" while the address went
 * to a log line on a serverless instance and vanished with it. "Not yet sent" and "not kept" are
 * different promises. A form that cannot keep an address says so.
 */

/* WHICH PUBLICATION AM I. `COPY.handle` is how the shell already answers that, so this reuses it
 * rather than adding a second identity for one route to disagree with. */
const PUBLICATION = COPY.handle.replace(/^@/, "");

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export async function POST(request: Request) {
  let body: { email?: string; trap?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ ok: false, error: "bad request" }, { status: 400 });
  }

  // A filled honeypot is never a person; answer 200 so the bot has nothing to learn.
  if (body.trap) return NextResponse.json({ ok: true });

  const email = (body.email || "").trim().toLowerCase();
  if (!EMAIL.test(email)) {
    return NextResponse.json({ ok: false, error: "that address doesn't look right" }, { status: 400 });
  }

  const url = process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) {
    console.error("[letter] SUPABASE_SERVICE_ROLE_KEY or SUPABASE_URL missing, address NOT stored");
    return NextResponse.json({ ok: false, error: "the list is not reachable right now" }, { status: 500 });
  }

  const { createClient } = await import("@supabase/supabase-js");
  const sb = createClient(url, key, { auth: { persistSession: false } });
  const { error } = await sb
    .from("publication_subscribers")
    // Re-subscribing is not an error and must not hand a returning reader a failure message.
    /* ⛔ `unsubscribed: false` IS LOAD-BEARING. Without it this upsert names only publication,
     * email and source, so ON CONFLICT DO UPDATE touched only those and a reader who had
     * unsubscribed stayed unsubscribed. The route answered ok, the page printed the success
     * line, and the letter lane's `unsubscribed=eq.false` query went on skipping them, so no
     * surface on the product could ever put them back. The unsubscribe page says in as many
     * words that the form takes them back in one field. Measured 2026-09-19 on a running build:
     * row read unsubscribed true, POST answered 200 ok, row still true. */
    .upsert(
      { publication: PUBLICATION, email, source: "letter-form", unsubscribed: false },
      { onConflict: "publication,email", ignoreDuplicates: false },
    );

  if (error) {
    console.error(`[letter] store failed for ${PUBLICATION}: ${error.message}`);
    return NextResponse.json({ ok: false, error: "the list is not reachable right now" }, { status: 500 });
  }

  return NextResponse.json({ ok: true });
}

